package com.hms.appointments;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/patients") public class PatientSearchController {private final TenantRepository tenants;private final PatientRepository patients;public PatientSearchController(TenantRepository t,PatientRepository p){tenants=t;patients=p;} @GetMapping public List<Patient> search(@PathVariable String tenantSlug,@RequestParam(required=false) String query){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));String q=query==null?"":query.toLowerCase();return patients.findAllByTenantId(tenant).stream().filter(p->q.isBlank()||p.getFullName().toLowerCase().contains(q)||p.getPhone().contains(q)||Objects.toString(p.getHospitalPatientId(),"").toLowerCase().contains(q)||Objects.toString(p.getAbhaId(),"").toLowerCase().contains(q)).toList();}}
